"""Configurable SQLite reader for the screener; this module owns no schema."""

import re
import sqlite3
from collections import defaultdict
from dataclasses import dataclass
from datetime import date
from decimal import Decimal
from typing import DefaultDict, Dict, Iterable, List, Mapping, Optional, Sequence, Tuple

from .screener import CompanySnapshot

_IDENTIFIER = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


@dataclass(frozen=True)
class SQLiteReadSchema:
    metric_table: str
    market_table: str
    metric_columns: Mapping[str, str]
    market_columns: Mapping[str, str]

    def __post_init__(self) -> None:
        identifiers = [self.metric_table, self.market_table]
        identifiers.extend(self.metric_columns.values())
        identifiers.extend(self.market_columns.values())
        if not all(_IDENTIFIER.fullmatch(item) for item in identifiers):
            raise ValueError("SQLite table and column identifiers must be allowlisted names")
        required_metric = {
            "symbol",
            "filing_date",
            "period_end",
            "metric",
            "value",
        }
        required_market = {"symbol", "as_of", "metric", "value"}
        if not required_metric.issubset(self.metric_columns):
            raise ValueError("metric_columns is missing required logical columns")
        if not required_market.issubset(self.market_columns):
            raise ValueError("market_columns is missing required logical columns")


class SQLiteSnapshotAdapter:
    """Read long-form metric rows through an explicitly supplied schema mapping."""

    def __init__(self, connection: sqlite3.Connection, schema: SQLiteReadSchema) -> None:
        self.connection = connection
        self.schema = schema

    def snapshots(
        self, as_of: date, symbols: Optional[Sequence[str]] = None
    ) -> Iterable[CompanySnapshot]:
        financial_rows = self._fetch_rows(
            self.schema.metric_table,
            self.schema.metric_columns,
            "filing_date",
            as_of,
            symbols,
        )
        market_rows = self._fetch_rows(
            self.schema.market_table,
            self.schema.market_columns,
            "as_of",
            as_of,
            symbols,
        )
        return _assemble_snapshots(financial_rows, market_rows, as_of)

    def _fetch_rows(
        self,
        table: str,
        columns: Mapping[str, str],
        date_field: str,
        as_of: date,
        symbols: Optional[Sequence[str]],
    ) -> List[sqlite3.Row]:
        logical_fields = list(columns)
        select = ", ".join(
            "{} AS {}".format(columns[field], field) for field in logical_fields
        )
        sql = "SELECT {} FROM {} WHERE {} <= ?".format(
            select, table, columns[date_field]
        )
        params: List[str] = [as_of.isoformat()]
        if symbols:
            sql += " AND {} IN ({})".format(
                columns["symbol"], ", ".join("?" for _ in symbols)
            )
            params.extend(symbols)
        sql += " ORDER BY {}, {}".format(columns["symbol"], columns[date_field])
        cursor = self.connection.execute(sql, params)
        names = [item[0] for item in cursor.description]
        return [dict(zip(names, row)) for row in cursor.fetchall()]  # type: ignore[return-value]


def _assemble_snapshots(
    financial_rows: Sequence[Mapping[str, object]],
    market_rows: Sequence[Mapping[str, object]],
    as_of: date,
) -> Tuple[CompanySnapshot, ...]:
    by_symbol_period: DefaultDict[
        str, DefaultDict[date, Dict[str, Tuple[date, Decimal]]]
    ] = defaultdict(lambda: defaultdict(dict))
    for row in financial_rows:
        symbol = str(row["symbol"])
        filing_date = date.fromisoformat(str(row["filing_date"])[:10])
        period_end = date.fromisoformat(str(row["period_end"])[:10])
        metric = str(row["metric"])
        value = Decimal(str(row["value"]))
        existing = by_symbol_period[symbol][period_end].get(metric)
        if existing is None or filing_date >= existing[0]:
            by_symbol_period[symbol][period_end][metric] = (filing_date, value)

    market_by_symbol: DefaultDict[str, Dict[str, Tuple[date, Decimal]]] = defaultdict(dict)
    for row in market_rows:
        symbol = str(row["symbol"])
        observed = date.fromisoformat(str(row["as_of"])[:10])
        metric = str(row["metric"])
        value = Decimal(str(row["value"]))
        existing = market_by_symbol[symbol].get(metric)
        if existing is None or observed >= existing[0]:
            market_by_symbol[symbol][metric] = (observed, value)

    snapshots = []
    for symbol, periods in by_symbol_period.items():
        ordered_periods = sorted(periods, reverse=True)
        if not ordered_periods:
            continue
        current_period = ordered_periods[0]
        prior_period = ordered_periods[1] if len(ordered_periods) > 1 else None
        metrics = {name: item[1] for name, item in periods[current_period].items()}
        prior = (
            {name: item[1] for name, item in periods[prior_period].items()}
            if prior_period
            else {}
        )
        market = {name: item[1] for name, item in market_by_symbol[symbol].items()}
        snapshots.append(
            CompanySnapshot(symbol, as_of, current_period, metrics, prior, market)
        )
    return tuple(sorted(snapshots, key=lambda item: item.symbol))

"""Secure, taxonomy-independent extraction of facts from XBRL instances."""

from datetime import date
from decimal import Decimal, InvalidOperation
from io import BytesIO
from typing import Dict, Iterable, List, Optional, Tuple

from lxml import etree

from .domain import (
    ContextRecord,
    Dimension,
    FactRecord,
    FilingIdentity,
    ParsedFiling,
    PeriodKind,
    UnitRecord,
)

XBRLI_NS = "http://www.xbrl.org/2003/instance"
XBRLDI_NS = "http://xbrl.org/2006/xbrldi"
XSI_NS = "http://www.w3.org/2001/XMLSchema-instance"
_STRUCTURAL_NAMES = {
    "context",
    "unit",
    "schemaRef",
    "linkbaseRef",
    "footnoteLink",
    "roleRef",
    "arcroleRef",
}


class XBRLParseError(ValueError):
    """Raised when an XBRL instance is unsafe or structurally invalid."""


def parse_xbrl(
    xml: bytes,
    identity: FilingIdentity,
    ignore_unknown_contexts: bool = False,
    allow_legacy_encoding: bool = False,
) -> ParsedFiling:
    """Parse an XBRL instance without resolving entities, DTDs, or networks."""
    if not isinstance(xml, bytes):
        raise TypeError("xml must be bytes")
    if b"<!DOCTYPE" in xml.upper() or b"<!ENTITY" in xml.upper():
        raise XBRLParseError("DTD and entity declarations are not allowed")

    parser = etree.XMLParser(
        resolve_entities=False,
        no_network=True,
        load_dtd=False,
        recover=False,
        huge_tree=False,
        remove_comments=True,
    )
    source_encoding_repair = None
    try:
        root = etree.parse(BytesIO(xml), parser).getroot()
    except (etree.XMLSyntaxError, ValueError) as exc:
        if not allow_legacy_encoding or "UTF-8" not in str(exc).upper():
            raise XBRLParseError("invalid XBRL XML: {}".format(exc)) from exc
        try:
            repaired = xml.decode("windows-1252").encode("utf-8")
            root = etree.parse(BytesIO(repaired), parser).getroot()
        except (UnicodeError, etree.XMLSyntaxError, ValueError) as repair_exc:
            raise XBRLParseError(
                "invalid XBRL XML after Windows-1252 repair: {}".format(repair_exc)
            ) from repair_exc
        source_encoding_repair = "windows-1252"

    contexts = tuple(_parse_context(node) for node in root.findall(_x("context")))
    context_by_id = {context.context_id: context for context in contexts}
    units = tuple(_parse_unit(node) for node in root.findall(_x("unit")))
    facts: List[FactRecord] = []
    unknown_context_fact_count = 0
    unknown_context_ids = set()

    for node in root.iterchildren():
        local_name = etree.QName(node).localname
        if local_name in _STRUCTURAL_NAMES:
            continue
        context_ref = node.get("contextRef")
        if not context_ref:
            continue
        try:
            context = context_by_id[context_ref]
        except KeyError as exc:
            if ignore_unknown_contexts:
                unknown_context_fact_count += 1
                unknown_context_ids.add(context_ref)
                continue
            raise XBRLParseError(
                "fact {} references unknown context {}".format(local_name, context_ref)
            ) from exc
        text = "".join(node.itertext()).strip()
        nil = node.get("{{{}}}nil".format(XSI_NS), "false").lower() in ("true", "1")
        facts.append(
            FactRecord(
                filing=identity,
                context=context,
                namespace=etree.QName(node).namespace or "",
                local_name=local_name,
                value=text,
                numeric_value=None if nil else _decimal_or_none(text),
                unit_ref=node.get("unitRef"),
                decimals=node.get("decimals"),
                precision=node.get("precision"),
                nil=nil,
            )
        )

    return ParsedFiling(
        identity,
        contexts,
        units,
        tuple(facts),
        unknown_context_fact_count,
        tuple(sorted(unknown_context_ids)),
        source_encoding_repair,
    )


def _x(local_name: str) -> str:
    return "{{{}}}{}".format(XBRLI_NS, local_name)


def _parse_date(text: Optional[str], label: str) -> date:
    if not text:
        raise XBRLParseError("context is missing {}".format(label))
    try:
        return date.fromisoformat(text.strip()[:10])
    except ValueError as exc:
        raise XBRLParseError("invalid {} date {!r}".format(label, text)) from exc


def _parse_context(node: etree._Element) -> ContextRecord:
    context_id = node.get("id")
    if not context_id:
        raise XBRLParseError("context is missing id")
    identifier = node.find("./{}/{}".format(_x("entity"), _x("identifier")))
    if identifier is None or not (identifier.text or "").strip():
        raise XBRLParseError("context {} is missing entity identifier".format(context_id))

    period = node.find(_x("period"))
    if period is None:
        raise XBRLParseError("context {} is missing period".format(context_id))
    instant_node = period.find(_x("instant"))
    start_node = period.find(_x("startDate"))
    end_node = period.find(_x("endDate"))
    forever_node = period.find(_x("forever"))
    if instant_node is not None:
        kind = PeriodKind.INSTANT
        instant = _parse_date(instant_node.text, "instant")
        start = end = None
    elif start_node is not None and end_node is not None:
        kind = PeriodKind.DURATION
        instant = None
        start = _parse_date(start_node.text, "start")
        end = _parse_date(end_node.text, "end")
        if end < start:
            raise XBRLParseError("context {} ends before it starts".format(context_id))
    elif forever_node is not None:
        kind = PeriodKind.FOREVER
        instant = start = end = None
    else:
        raise XBRLParseError("context {} has an invalid period".format(context_id))

    dimensions = tuple(_parse_dimensions(node))
    return ContextRecord(
        context_id=context_id,
        entity_identifier=(identifier.text or "").strip(),
        entity_scheme=identifier.get("scheme"),
        period_kind=kind,
        period_start=start,
        period_end=end,
        instant=instant,
        dimensions=dimensions,
    )


def _parse_dimensions(node: etree._Element) -> Iterable[Dimension]:
    namespaces: Dict[Optional[str], str] = dict(node.nsmap)
    for member in node.findall(".//{{{}}}explicitMember".format(XBRLDI_NS)):
        dimension_ns, dimension_name = _resolve_qname(member.get("dimension"), namespaces)
        member_ns, member_name = _resolve_qname((member.text or "").strip(), namespaces)
        yield Dimension(dimension_ns, dimension_name, member_ns, member_name)
    for member in node.findall(".//{{{}}}typedMember".format(XBRLDI_NS)):
        dimension_ns, dimension_name = _resolve_qname(member.get("dimension"), namespaces)
        child = next(iter(member), None)
        member_ns = etree.QName(child).namespace or "" if child is not None else ""
        member_name = etree.QName(child).localname if child is not None else ""
        typed_value = "".join(child.itertext()).strip() if child is not None else ""
        yield Dimension(
            dimension_ns,
            dimension_name,
            member_ns,
            member_name,
            typed_value=typed_value,
        )


def _resolve_qname(
    lexical: Optional[str], namespaces: Dict[Optional[str], str]
) -> Tuple[str, str]:
    if not lexical:
        return "", ""
    if ":" not in lexical:
        return namespaces.get(None, ""), lexical
    prefix, local_name = lexical.split(":", 1)
    return namespaces.get(prefix, ""), local_name


def _parse_unit(node: etree._Element) -> UnitRecord:
    unit_id = node.get("id")
    if not unit_id:
        raise XBRLParseError("unit is missing id")
    direct_measures = tuple(_measure_text(item) for item in node.findall(_x("measure")))
    divide = node.find(_x("divide"))
    if divide is None:
        return UnitRecord(unit_id=unit_id, measures=direct_measures)
    numerator = tuple(
        _measure_text(item)
        for item in divide.findall("./{}/{}".format(_x("unitNumerator"), _x("measure")))
    )
    denominator = tuple(
        _measure_text(item)
        for item in divide.findall("./{}/{}".format(_x("unitDenominator"), _x("measure")))
    )
    return UnitRecord(
        unit_id=unit_id,
        measures=(),
        numerator_measures=numerator,
        denominator_measures=denominator,
    )


def _measure_text(node: etree._Element) -> str:
    return (node.text or "").strip()


def _decimal_or_none(value: str) -> Optional[Decimal]:
    normalized = value.strip().replace(",", "")
    if not normalized:
        return None
    try:
        return Decimal(normalized)
    except InvalidOperation:
        return None

"""Bounded-concurrency historical archive backfill with serialized DB writes."""

import logging
import threading
import time
from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait
from dataclasses import dataclass
from datetime import date, timedelta
from typing import Callable, Dict, Iterable, List, Optional, Sequence, Tuple

from market_data.calendar import is_trading_day, trading_days
from market_data.database import MarketDatabase


logger = logging.getLogger(__name__)
PUBLIC_BOUNDARIES = {"nse": date(1994, 11, 3), "bse": date(2006, 3, 1)}
RECENT_GAP_DAYS = 10


@dataclass
class DownloadResult:
    source: str
    trading_date: date
    status: str
    records: Sequence[Dict[str, object]]
    error: Optional[Exception] = None


@dataclass
class BackfillResult:
    attempted: int = 0
    succeeded: int = 0
    unavailable: int = 0
    failed: int = 0
    rows_written: int = 0
    interrupted: bool = False


def classify_download_error(error: Exception, trading_date: date, end: date) -> str:
    text = str(error).lower()
    transient = (
        "403" in text
        or "429" in text
        or any(" {} ".format(code) in " {} ".format(text) for code in range(500, 600))
        or "timeout" in text
        or "connection" in text
        or "circuit open" in text
    )
    unavailable = (
        "404" in text
        or "not found" in text
    )
    if (
        unavailable
        and not transient
        and trading_date < end - timedelta(days=RECENT_GAP_DAYS)
    ):
        return "not_published"
    return "failed"


class ConcurrentArchiveFetcher:
    """Give each worker its own source/client while sharing host throttling."""

    def __init__(self, source_factory: Callable[[str], object]):
        self.source_factory = source_factory
        self.local = threading.local()
        self._clients = []
        self._lock = threading.Lock()

    def __call__(self, source: str, trading_date: date):
        sources = getattr(self.local, "sources", None)
        if sources is None:
            sources = {}
            self.local.sources = sources
        if source not in sources:
            source_object = self.source_factory(source)
            sources[source] = source_object
            with self._lock:
                self._clients.append(source_object.client)
        return sources[source].fetch_bhavcopy(trading_date)

    def close(self) -> None:
        with self._lock:
            clients, self._clients = self._clients, []
        for client in clients:
            client.close()


class HistoricalBackfill:
    def __init__(
        self,
        database: MarketDatabase,
        fetch: Callable[[str, date], Sequence[Dict[str, object]]],
        workers: int = 4,
        progress_interval: float = 30.0,
    ):
        if workers < 1 or workers > 16:
            raise ValueError("workers must be between 1 and 16")
        self.database = database
        self.fetch = fetch
        self.workers = workers
        self.progress_interval = progress_interval

    def plan(
        self,
        sources: Iterable[str],
        starts: Dict[str, date],
        end: date,
        only_failures: bool = False,
    ) -> List[Tuple[str, date]]:
        planned = []
        for source in sources:
            start = max(starts[source], PUBLIC_BOUNDARIES[source])
            if start > end:
                continue
            unavailable_months = self.database.unavailable_months(source)
            if only_failures:
                dates = self.database.checkpoint_dates(
                    source, "daily_prices", start, end, ("failed",)
                )
            else:
                terminal = self.database.checkpoint_dates(
                    source,
                    "daily_prices",
                    start,
                    end,
                    ("success", "holiday", "not_published"),
                )
                dates = {
                    item
                    for item in trading_days(start, end)
                    if item.strftime("%Y-%m") not in unavailable_months
                } - terminal
            planned.extend((source, item) for item in sorted(dates))
        return sorted(planned, key=lambda item: (item[1], item[0]))

    def run(
        self,
        plan: Sequence[Tuple[str, date]],
        end: date,
        dry_run: bool = False,
    ) -> BackfillResult:
        result = BackfillResult(attempted=len(plan) if dry_run else 0)
        if dry_run or not plan:
            return result
        run_ids = {
            source: self.database.start_run(source, "daily_prices")
            for source in sorted({item[0] for item in plan})
        }
        started = time.monotonic()
        last_log = started
        futures = {}
        iterator = iter(plan)
        disabled_sources = set()
        blocked_counts = {source: 0 for source in run_ids}
        fatal_error = None
        source_stats = {
            source: {"attempted": 0, "succeeded": 0, "failed": 0, "rows": 0}
            for source in run_ids
        }
        executor = ThreadPoolExecutor(max_workers=self.workers)

        def submit_one() -> bool:
            while True:
                try:
                    source, trading_date = next(iterator)
                except StopIteration:
                    return False
                if source not in disabled_sources:
                    break
            future = executor.submit(self._download, source, trading_date, end)
            futures[future] = (source, trading_date)
            result.attempted += 1
            source_stats[source]["attempted"] += 1
            return True

        try:
            for _ in range(min(len(plan), self.workers * 2)):
                submit_one()
            while futures:
                done, _ = wait(futures, return_when=FIRST_COMPLETED)
                for future in done:
                    futures.pop(future)
                    item = future.result()
                    self._write(run_ids[item.source], item, result)
                    if item.status == "success":
                        source_stats[item.source]["succeeded"] += 1
                        source_stats[item.source]["rows"] += len(item.records)
                    elif item.status == "failed":
                        source_stats[item.source]["failed"] += 1
                    error_text = str(item.error).lower() if item.error else ""
                    if item.status == "failed" and (
                        "403" in error_text or "circuit open" in error_text
                    ):
                        blocked_counts[item.source] += 1
                        if blocked_counts[item.source] >= self.workers:
                            disabled_sources.add(item.source)
                            logger.error(
                                "%s archive host appears rate-blocked; pausing this "
                                "exchange until a later resume",
                                item.source.upper(),
                            )
                    elif item.status == "success":
                        blocked_counts[item.source] = 0
                    submit_one()
                now = time.monotonic()
                if now - last_log >= self.progress_interval:
                    complete = result.succeeded + result.unavailable + result.failed
                    rate = complete / max(now - started, 0.001)
                    remaining = len(plan) - complete
                    logger.info(
                        "backfill progress %d/%d (%.1f%%), rows=%d, failures=%d, ETA=%s",
                        complete,
                        len(plan),
                        100.0 * complete / len(plan),
                        result.rows_written,
                        result.failed,
                        self._eta(remaining, rate),
                    )
                    last_log = now
        except KeyboardInterrupt:
            result.interrupted = True
            for future in futures:
                future.cancel()
        except BaseException as error:
            fatal_error = error
            for future in futures:
                future.cancel()
            raise
        finally:
            executor.shutdown(wait=True, cancel_futures=True)
            for source, run_id in run_ids.items():
                stats = source_stats[source]
                self.database.finish_run(
                    run_id,
                    "interrupted" if result.interrupted else (
                        "failed"
                        if fatal_error or stats["failed"] or source in disabled_sources
                        else "success"
                    ),
                    stats["attempted"],
                    stats["succeeded"],
                    stats["failed"],
                    stats["rows"],
                    "Host circuit opened; resume after cooldown"
                    if source in disabled_sources
                    else str(fatal_error) if fatal_error else "",
                )
            for source, year_month in {
                (source, trading_date.strftime("%Y-%m"))
                for source, trading_date in plan
            }:
                self.database.refresh_month_availability(source, year_month)
        return result

    def _download(self, source: str, trading_date: date, end: date) -> DownloadResult:
        try:
            records = self.fetch(source, trading_date)
            return DownloadResult(source, trading_date, "success", records)
        except Exception as error:
            return DownloadResult(
                source,
                trading_date,
                classify_download_error(error, trading_date, end),
                (),
                error,
            )

    def _write(
        self, run_id: int, item: DownloadResult, result: BackfillResult
    ) -> None:
        key = item.trading_date.isoformat()
        if item.status == "success":
            written = self.database.upsert_prices(item.records)
            self.database.record_checkpoint(
                item.source,
                "daily_prices",
                key,
                "success",
                checkpoint_date=item.trading_date,
                row_count=written,
            )
            result.succeeded += 1
            result.rows_written += written
            return
        self.database.record_checkpoint(
            item.source,
            "daily_prices",
            key,
            item.status,
            checkpoint_date=item.trading_date,
            error=str(item.error),
        )
        if item.status == "not_published":
            result.unavailable += 1
            logger.debug("%s %s archive not published", item.source.upper(), key)
        else:
            result.failed += 1
            self.database.record_error(
                run_id, item.source, "daily_prices", key, item.error or RuntimeError(key)
            )
            logger.error("%s %s failed: %s", item.source.upper(), key, item.error)

    @staticmethod
    def _eta(remaining: int, rate: float) -> str:
        if rate <= 0:
            return "unknown"
        seconds = int(remaining / rate)
        return "{}h{:02d}m".format(seconds // 3600, seconds % 3600 // 60)


def coverage_report(
    database: MarketDatabase,
    sources: Iterable[str],
    starts: Dict[str, date],
    end: date,
) -> List[Dict[str, object]]:
    reports = []
    for source in sources:
        start = max(starts[source], PUBLIC_BOUNDARIES[source])
        snapshot = database.coverage_snapshot(source, start, end)
        expected = set(trading_days(start, end))
        present = snapshot.pop("present_dates")
        missing = sorted(expected - present)
        snapshot.update(
            expected_days=len(expected),
            missing_days=len(missing),
            missing_dates=missing,
        )
        reports.append(snapshot)
    return reports

"""Conservative Indian cash-equity trading calendar helpers."""

from datetime import date, datetime, timedelta
from typing import Iterable, Optional, Set
from zoneinfo import ZoneInfo


IST = ZoneInfo("Asia/Kolkata")


def _easter_sunday(year: int) -> date:
    a = year % 19
    b, c = divmod(year, 100)
    d, e = divmod(b, 4)
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i, k = divmod(c, 4)
    weekday = (32 + 2 * e + 2 * i - h - k) % 7
    month = (a + 11 * h + 22 * weekday) // 451
    return date(year, (h + weekday - 7 * month + 114) // 31, ((h + weekday - 7 * month + 114) % 31) + 1)


def reliable_holidays(year: int) -> Set[date]:
    """Holidays that are fixed or algorithmically stable across NSE and BSE."""
    easter = _easter_sunday(year)
    return {
        date(year, 1, 26),
        easter - timedelta(days=2),
        date(year, 8, 15),
        date(year, 10, 2),
        date(year, 12, 25),
    }


def is_trading_day(value: date) -> bool:
    return value.weekday() < 5 and value not in reliable_holidays(value.year)


def trading_days(start: date, end: date) -> Iterable[date]:
    current = start
    while current <= end:
        if is_trading_day(current):
            yield current
        current += timedelta(days=1)


def last_completed_trading_day(now: Optional[datetime] = None) -> date:
    current = now.astimezone(IST) if now else datetime.now(IST)
    candidate = current.date()
    if current.hour < 18:
        candidate -= timedelta(days=1)
    while not is_trading_day(candidate):
        candidate -= timedelta(days=1)
    return candidate
